using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Xml.Serialization;
class TopologyVariantsTests {
 static void Need(bool x,string s){if(!x)throw new Exception(s);}
 static DiscoveryResult CheckModel(int physicalPerCcd,int ccdCount,string name){var root=AppDomain.CurrentDomain.BaseDirectory;CpuCatalog catalog;using(var r=File.OpenRead(Path.Combine(root,"Reference","AMD-processors.xml")))catalog=(CpuCatalog)new XmlSerializer(typeof(CpuCatalog)).Deserialize(r);var model=CcdDiscovery.Match(name,catalog);Need(model!=null,"official model match: "+name);Need(model.OneL3PerCcd,"CCD architecture eligibility: "+name);var cpus=new List<Cpu>();var probe=new ProbeReport{Vendor="AuthenticAMD",Brand=name,Family=25};var caches=new List<CacheDomain>();var physical=new List<CacheDomain>();int logical=0;for(int die=0;die<ccdCount;die++){var keys=new List<string>();for(int core=0;core<physicalPerCcd;core++)for(int smt=0;smt<2;smt++){string key="0:"+logical;keys.Add(key);cpus.Add(new Cpu{Group=0,Index=(byte)logical,Core=(byte)(die*physicalPerCcd+core),Cache=(byte)die});probe.Cpus.Add(new ProbeCpu{Group=0,Index=logical,WindowsCore=die*physicalPerCcd+core,WindowsL3=die,L3Domain=die,HardwareCore=core,ApicId=die*32+core*2+smt,L3SizeKiB=32768,L3Sharing=physicalPerCcd*2});logical++;}caches.Add(new CacheDomain{Cores=keys.ToArray(),Bytes=33554432});physical.AddRange(Enumerable.Range(0,physicalPerCcd).Select(core=>new CacheDomain{Cores=new[]{keys[core*2],keys[core*2+1]}}));}return CcdDiscovery.Evaluate(cpus,probe,model,caches,physical);}
 static void Main(){try{var a=CheckModel(6,2,"AMD Ryzen 9 5900X 12-Core Processor");Need(a.Ready&&a.Groups.Count==2&&a.Groups.All(g=>g.Cores.Length==12),"12-core two-CCD layout");var b=CheckModel(8,1,"AMD Ryzen 7 9800X3D 8-Core Processor");Need(b.Ready&&b.Groups.Count==1&&b.Groups[0].Cores.Length==16,"8-core single-CCD layout");var c=CheckModel(6,4,"AMD Ryzen Threadripper PRO 7965WX 24-Cores");if(!c.Ready)Console.WriteLine(c.Reason);Need(c.Ready&&c.Groups.Count==4&&c.Groups.Sum(g=>g.Cores.Length)==48,"partially populated four-CCD workstation layout");var root=AppDomain.CurrentDomain.BaseDirectory;CpuCatalog catalog;using(var r=File.OpenRead(Path.Combine(root,"Reference","AMD-processors.xml")))catalog=(CpuCatalog)new XmlSerializer(typeof(CpuCatalog)).Deserialize(r);var apu=CcdDiscovery.Match("AMD Ryzen 7 5700G with Radeon Graphics",catalog);Need(apu!=null&&!apu.OneL3PerCcd,"monolithic APU stays in manual-review mode");var m=AppStore.Clone(new Settings{DefaultCcd="CCD3",CCD1=new string[0],CcdGroups=new List<CcdGroup>{new CcdGroup{Number=0,Cores=new[]{"0:0"}},new CcdGroup{Number=1,Cores=new[]{"0:1"}},new CcdGroup{Number=2,Cores=new[]{"0:2"}},new CcdGroup{Number=3,Cores=new[]{"0:3"}}}});Need(CcdDiscovery.Default(m)=="CCD3","default CCD choice supports larger CCD counts");Console.WriteLine("PASS variable AMD model matching and 1/2/4 CCD topology sizes");}catch(Exception ex){Console.WriteLine(ex.GetType().FullName+" : "+ex.Message);Environment.ExitCode=1;}}
}


